from pathlib import Path
import base64,json,os,re,subprocess,sys,tempfile
ROOT=Path.home()
FRONT=ROOT/'ASTRA-Frontend-latest'
BACK=ROOT/'ASTRA-Backend-latest'
contents=json.loads(base64.b64decode(''))
original={}
updated={}
for relative,content in contents.items():
    p=ROOT/relative
    original[p]=p.read_text(encoding='utf-8-sig') if p.exists() else None
    if relative.endswith('FeatureTicketQa.cs') and original[p] is not None and original[p]!=content:
        raise SystemExit('STOP: an existing QA service differs. No files changed.')
    updated[p]=content
p=FRONT/'src/pages/ticket-workspace.tsx'
original[p]=p.read_text(encoding='utf-8-sig')
f=original[p]
old='                    comments={detail.comments}\n                    attachments={detail.attachments}\n                    approvals={detail.approvals}'
new='                    request={request}\n                    onSaved={refresh}'
if new not in f:
    if f.count(old)!=1:raise SystemExit('STOP: QA component props differ. No files changed.')
    f=f.replace(old,new,1)
qa_case=json.loads(base64.b64decode(''))
if "case 'TICKET.QA_REVIEWED':" not in f:
    anchor="    case 'TICKET.TAGS_CHANGED':"
    if f.count(anchor)!=1:raise SystemExit('STOP: activity formatter differs. No files changed.')
    f=f.replace(anchor,qa_case+anchor,1)
updated[p]=f
p=BACK/'FeatureApis.cs'
original[p]=p.read_text(encoding='utf-8-sig')
b=original[p]
if '        MapTicketQa(api);' not in b:
    if b.count('        MapProblemEdits(api);')!=1:raise SystemExit('STOP: API mapping differs. No files changed.')
    b=b.replace('        MapProblemEdits(api);','        MapProblemEdits(api);\n        MapTicketQa(api);',1)
updated[p]=b
p=BACK/'Program.cs'
original[p]=p.read_text(encoding='utf-8-sig')
b=original[p]
privacy='        if (!isWide) history.RemoveAll(entry => Equals(entry.GetValueOrDefault("action"), "TICKET.QA_REVIEWED"));\n'
if privacy not in b:
    marker='        await AddTicketAssignmentNames('
    if b.count(marker)!=1:raise SystemExit('STOP: ticket history enrichment differs. No files changed.')
    b=b.replace(marker,privacy+marker,1)
updated[p]=b
paths=list(updated)
print('QA update: compact modal, four ratings, comment, reviewer history and audit.',flush=True)
print('Uses existing ticket history. No database schema or account changes.',flush=True)
if '--apply' not in sys.argv:raise SystemExit('REVIEW ONLY: no source files changed.')
# Confirm a single owned Development preview before touching source.
listeners = subprocess.check_output(['ss','-ltnp','sport = :5200'], text=True)
pids = set(re.findall(r'pid=(\d+)', listeners))
if len(pids) != 1: raise SystemExit('STOP: expected one existing backend on port 5200.')
proc = Path('/proc') / pids.pop()
if proc.stat().st_uid != os.getuid() or (proc/'cwd').resolve() != BACK.resolve():
    raise SystemExit('STOP: backend owner or project folder differs.')
env = dict(part.split(b'=',1) for part in (proc/'environ').read_bytes().split(b'\0') if b'=' in part)
env = {os.fsdecode(k):os.fsdecode(v) for k,v in env.items()}
if (env.get('DOTNET_ENVIRONMENT') or env.get('ASPNETCORE_ENVIRONMENT')) != 'Development':
    raise SystemExit('STOP: only the Development preview can be updated.')
if env.get('ASPNETCORE_URLS') != 'http://127.0.0.1:5200':
    raise SystemExit('STOP: expected loopback-only preview.')
helper = BACK/'local-maintenance/restart-ticket-preview.py'
if not helper.is_file(): raise SystemExit('STOP: project restart helper is missing.')
try:
    for p in paths:
        if updated[p] != original[p]: p.write_text(updated[p], encoding='utf-8')
    subprocess.run(['npm','run','build'], cwd=FRONT, check=True)
    build = tempfile.mkdtemp(prefix='astra-ticket-ready.', dir='/tmp')
    subprocess.run(['dotnet','build','Astra.Api.csproj','-o',build], cwd=BACK, check=True)
    subprocess.run(['python3',str(helper),build], cwd=BACK, check=True)
except BaseException:
    for p in paths:
        if original[p] is None:
            if p.exists(): p.unlink()
        elif updated[p] != original[p]: p.write_text(original[p], encoding='utf-8')
    print('Update failed; original source restored from memory. No backup files created.', flush=True)
    raise
print('SUCCESS: Ubuntu QA review update is healthy. Refresh the ticket page.', flush=True)
